function Copy-ApplicationSource {
    <# .SYNOPSIS Additively copies project sources to AppRoot with robocopy (no /MIR, /PURGE or deletes), excluding secrets, build output and Android folders. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config)
    $src = $Config.SourceRoot.TrimEnd('\')
    $dst = $Config.AppRoot.TrimEnd('\')
    if ($src -ieq $dst) { throw 'SourceRoot and AppRoot are identical; refusing to copy onto itself.' }
    if (-not (Test-Path -LiteralPath (Join-Path $src 'server\package.json'))) { throw "SourceRoot does not look like the Garage project: $src" }
    if (-not $PSCmdlet.ShouldProcess($dst, "Copy sources from $src (additive)")) { return }
    $xd = @('.git', 'node_modules', 'dist', '.expo', 'android', 'ios', 'build', 'backups', '.playwright-mcp')
    $xf = @('.env', '.env.*', '*.env', '*.jks', '*.keystore', '*.pfx', '*.p12', '*.pem', '*.key', '*.license', '*.apk', '*.aab', '*.log', '*.zip')
    foreach ($dir in @('shared', 'server', 'deploy')) {
        $args = @((Join-Path $src $dir), (Join-Path $dst $dir), '/E', '/COPY:DAT', '/R:2', '/W:2', '/NFL', '/NDL', '/NJH', '/NJS', '/XD') + $xd + @('/XF') + $xf
        $r = Invoke-Native -FilePath 'robocopy.exe' -Arguments $args -AllowFailure
        if ($r.ExitCode -ge 8) { throw "robocopy failed for $dir (exit $($r.ExitCode))`n$($r.Output -join "`n")" }
    }
    New-Item -ItemType Directory -Force -Path (Join-Path $dst 'mobile') | Out-Null
    foreach ($file in @('package.json', 'package-lock.json', 'README.md')) {
        if (Test-Path -LiteralPath (Join-Path $src $file)) { Copy-Item -LiteralPath (Join-Path $src $file) -Destination (Join-Path $dst $file) -Force }
    }
    Copy-Item -LiteralPath (Join-Path $src 'mobile\package.json') -Destination (Join-Path $dst 'mobile\package.json') -Force
}

function Invoke-ServerBuild {
    <# .SYNOPSIS Installs only shared+server workspace dependencies (no scripts) and builds the production server. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config)
    if (-not $PSCmdlet.ShouldProcess($Config.AppRoot, 'npm ci (shared, server workspaces) and npm run build')) { return }
    $npm = Join-Path (Split-Path $Config.NodePath) 'npm.cmd'
    Push-Location -LiteralPath $Config.AppRoot
    try {
        Invoke-Native -FilePath $npm -Arguments @('ci', '--workspace', '@garage/shared', '--workspace', '@garage/server', '--ignore-scripts') -Passthru
        if ($LASTEXITCODE -ne 0) { throw 'npm ci failed.' }
        Invoke-Native -FilePath $npm -Arguments @('run', 'build') -Passthru
        if ($LASTEXITCODE -ne 0) { throw 'npm run build failed.' }
    } finally { Pop-Location }
    foreach ($f in @('main.js', 'migrate.js', 'bootstrap.js', 'worker.js', 'backup.js')) {
        if (-not (Test-Path -LiteralPath (Join-Path $Config.AppRoot "server\dist\$f"))) { throw "Build output missing: server\dist\$f" }
    }
}

function Get-WinSWConfigXml {
    <# .SYNOPSIS Generates the WinSW XML from GarageManager.xml with node, env-file, entry point, working and log paths set from the actual configuration. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config)
    $xml = New-Object Xml.XmlDocument
    $xml.PreserveWhitespace = $true
    $xml.Load((Join-Path $Config.ScriptRoot 'GarageManager.xml'))
    $svc = $xml.DocumentElement
    $svc.SelectSingleNode('id').InnerText = $Config.ServiceName
    $svc.SelectSingleNode('executable').InnerText = $Config.NodePath
    $svc.SelectSingleNode('arguments').InnerText = "--env-file=`"$($Config.EnvFile)`" `"$([IO.Path]::Combine($Config.AppRoot, 'server\dist\main.js'))`""
    $svc.SelectSingleNode('workingdirectory').InnerText = $Config.AppRoot
    $svc.SelectSingleNode('logpath').InnerText = $Config.LogDir
    return $xml.OuterXml
}

function Test-WinSWBinary {
    <# .SYNOPSIS Accepts a WinSW executable only with a caller-supplied SHA-256 match or a valid Authenticode signature; never trusts an unverified binary. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][string]$Path, [string]$ExpectedSha256)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw "WinSW executable not found: $Path" }
    if ($ExpectedSha256) {
        $actual = (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash
        if ($actual -ne $ExpectedSha256.ToUpperInvariant()) { throw "WinSW SHA-256 mismatch. Expected $ExpectedSha256, got $actual." }
        return $true
    }
    $sig = Get-AuthenticodeSignature -LiteralPath $Path
    if ($sig.Status -eq 'Valid') { return $true }
    throw "WinSW is not Authenticode-signed (status $($sig.Status)) and no -WinSWSha256 was supplied. WinSW publishes no checksum file; verify the release yourself and pass its SHA-256."
}

function Install-GarageService {
    <# .SYNOPSIS After approval, installs or refreshes the WinSW LocalService service, refusing to touch a same-named service that is not ours. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config)
    Test-WinSWBinary -Path $Config.WinSWPath -ExpectedSha256 $Config.WinSWSha256 | Out-Null
    $exe = Join-Path $Config.ServiceRoot "$($Config.ServiceName).exe"
    $xmlPath = Join-Path $Config.ServiceRoot "$($Config.ServiceName).xml"
    $existing = Get-CimInstance Win32_Service -Filter "Name='$($Config.ServiceName)'" -ErrorAction SilentlyContinue
    if ($existing -and $existing.PathName -notmatch [regex]::Escape($exe)) {
        throw "A service named $($Config.ServiceName) exists but is not this WinSW wrapper ($($existing.PathName)). Resolve the conflict manually."
    }
    if (-not (Request-Approval -Action 'Install/refresh Windows service' -Target $Config.ServiceName -Detail "WinSW at $exe, runs as NT AUTHORITY\LocalService, node $($Config.NodePath)" -Required)) { return }
    Copy-Item -LiteralPath $Config.WinSWPath -Destination $exe -Force
    [IO.File]::WriteAllText($xmlPath, (Get-WinSWConfigXml -Config $Config), (New-Object Text.UTF8Encoding $false))
    Invoke-Native -FilePath 'icacls.exe' -Arguments @($Config.AppRoot, '/grant', '*S-1-5-19:(OI)(CI)RX') | Out-Null
    if ($existing) { Invoke-Native -FilePath $exe -Arguments @('refresh') | Out-Null }
    else { Invoke-Native -FilePath $exe -Arguments @('install') | Out-Null }
}

function Assert-LocalServiceReadOnly {
    <# .SYNOPSIS Warns when LocalService holds write access on application code. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config)
    $acl = Get-Acl -LiteralPath $Config.AppRoot
    $ls = New-Object Security.Principal.SecurityIdentifier('S-1-5-19')
    $bad = $acl.Access | Where-Object {
        $_.AccessControlType -eq 'Allow' -and ($_.FileSystemRights -band [Security.AccessControl.FileSystemRights]::WriteData) -and
        ($_.IdentityReference.Translate([Security.Principal.SecurityIdentifier]) -eq $ls)
    }
    if ($bad) { Write-Warning 'LocalService has write access to the application directory; remove it.' }
}

function Wait-LoopbackHealth {
    <# .SYNOPSIS Polls http://127.0.0.1:port/health and throws explicitly when it never reports status ok. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config, [int]$TimeoutSeconds = 45)
    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
    $last = $null
    do {
        try {
            $r = Invoke-RestMethod -Uri "http://127.0.0.1:$($Config.ApiPort)/health" -TimeoutSec 5
            if ($r.status -eq 'ok') { Write-Info 'Loopback /health: ok'; return }
            $last = "unexpected body: $($r | ConvertTo-Json -Compress)"
        } catch { $last = $_.Exception.Message }
        Start-Sleep -Seconds 2
    } while ((Get-Date) -lt $deadline)
    throw "Loopback health check FAILED after ${TimeoutSeconds}s: $last. Inspect $($Config.LogDir)."
}

function Start-GarageService {
    <# .SYNOPSIS Starts the service via WinSW when stopped, then verifies loopback health. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config)
    $exe = Join-Path $Config.ServiceRoot "$($Config.ServiceName).exe"
    if (-not $PSCmdlet.ShouldProcess($Config.ServiceName, 'Start service and verify loopback health')) { return }
    if ((Get-Service -Name $Config.ServiceName).Status -ne 'Running') { Invoke-Native -FilePath $exe -Arguments @('start') | Out-Null }
    Wait-LoopbackHealth -Config $Config
    $listen = Get-NetTCPConnection -State Listen -LocalPort $Config.ApiPort -ErrorAction SilentlyContinue | Where-Object { $_.LocalAddress -notin @('127.0.0.1', '::1') }
    if ($listen) { throw "Port $($Config.ApiPort) is listening on a non-loopback address ($($listen.LocalAddress -join ', ')); investigate." }
}

function Register-GarageTasks {
    <# .SYNOPSIS After approval, registers the reminder (5 min) and daily backup tasks as LocalService with no overlap, pointing at the deployed Run-*.ps1 scripts. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config)
    if (-not (Request-Approval -Action 'Register scheduled tasks GarageManager-Reminders and GarageManager-Backup' -Target 'Task Scheduler (LocalService)' -Detail "Replaces only tasks with these exact names. Backup time: $($Config.BackupTime)")) { return }
    $ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $common = "-AppRoot `"$($Config.AppRoot)`" -EnvironmentFile `"$($Config.EnvFile)`" -NodePath `"$($Config.NodePath)`""
    $principal = New-ScheduledTaskPrincipal -UserId 'S-1-5-19' -LogonType ServiceAccount -RunLevel Limited
    $settings = New-ScheduledTaskSettingsSet -MultipleInstances IgnoreNew -StartWhenAvailable -ExecutionTimeLimit (New-TimeSpan -Hours 1)
    $remind = New-ScheduledTaskAction -Execute $ps -Argument "-NoProfile -NonInteractive -File `"$($Config.AppRoot)\deploy\windows\Run-Reminders.ps1`" $common" -WorkingDirectory $Config.AppRoot
    $backup = New-ScheduledTaskAction -Execute $ps -Argument "-NoProfile -NonInteractive -File `"$($Config.AppRoot)\deploy\windows\Run-Backup.ps1`" $common -BackupDirectory `"$($Config.BackupDir)`"" -WorkingDirectory $Config.AppRoot
    $everyFive = New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(2) -RepetitionInterval (New-TimeSpan -Minutes 5) -RepetitionDuration (New-TimeSpan -Days 3650)
    $daily = New-ScheduledTaskTrigger -Daily -At $Config.BackupTime
    Register-ScheduledTask -TaskName 'GarageManager-Reminders' -Action $remind -Trigger $everyFive -Principal $principal -Settings $settings -Force | Out-Null
    Register-ScheduledTask -TaskName 'GarageManager-Backup' -Action $backup -Trigger $daily -Principal $principal -Settings $settings -Force | Out-Null
}



function Get-WinSWDownload {
    <# .SYNOPSIS After approval, downloads the official WinSW 2.12.0 x64 release from github.com/winsw/winsw, shows its SHA-256 and signer, and accepts it only if you type a SHA-256 you verified independently (release page / your own review) or it carries a valid Authenticode signature; the file is deleted otherwise. Sets Config.WinSWPath/WinSWSha256. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config)
    $url = 'https://github.com/winsw/winsw/releases/download/v2.12.0/WinSW-x64.exe'
    $detail = "Downloads $url (official WinSW 2.x release matching GarageManager.xml). WinSW publishes no checksum file, so after download you must enter a SHA-256 you verified yourself, or the file must have a valid Authenticode signature. Otherwise it is deleted."
    if (-not (Request-Approval -Action 'Download WinSW' -Target 'github.com/winsw/winsw' -Detail $detail)) { return $null }
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    $target = Join-Path (Get-DownloadDirectory) 'WinSW-2.12.0-x64.exe'
    Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $target
    $actual = (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash
    $sig = Get-AuthenticodeSignature -LiteralPath $target
    Write-Info "Downloaded SHA-256: $actual"
    Write-Info "Authenticode status: $($sig.Status) $(if ($sig.SignerCertificate) { $sig.SignerCertificate.Subject })"
    if ($sig.Status -eq 'Valid') {
        if (Request-Approval -Action 'Trust this validly signed WinSW binary' -Target $target -Detail "Signer: $($sig.SignerCertificate.Subject)") { $Config.WinSWPath = $target; $Config.WinSWSha256 = $actual; return $target }
    } else {
        $typed = Read-Host 'Enter the SHA-256 you independently verified for this WinSW file (blank to reject)'
        if ($typed -and (($typed -replace '[\s:]', '').ToUpperInvariant() -eq $actual)) { $Config.WinSWPath = $target; $Config.WinSWSha256 = $actual; return $target }
    }
    Remove-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue
    throw 'WinSW was not verified (hash mismatch, no verified hash entered, or declined); the download was deleted.'
}
